draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Draw door
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.beginPath();
  ctx.rect(W/2 - 50, H/2 - 100, 100, 200);
  ctx.stroke();

  // Draw dog
  ctx.beginPath();
  ctx.arc(W/2 - 70, H/2 + 50, 30, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 + 30);
  ctx.lineTo(W/2 - 70, H/2 + 80);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 + 50);
  ctx.lineTo(W/2 - 90, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 + 50);
  ctx.lineTo(W/2 - 50, H/2 + 70);
  ctx.stroke();

  // Draw ears
  ctx.beginPath();
  ctx.moveTo(W/2 - 80, H/2 + 20);
  ctx.lineTo(W/2 - 60, H/2 + 10);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 60, H/2 + 20);
  ctx.lineTo(W/2 - 40, H/2 + 10);
  ctx.stroke();

  // Draw tail
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 + 90);
  ctx.lineTo(W/2 - 90 + 20 * Math.sin(t), H/2 + 110);
  ctx.stroke();

  // Draw eyes and mouth
  ctx.beginPath();
  ctx.arc(W/2 - 75, H/2 + 35, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2 - 65, H/2 + 35, 5, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 70, H/2 + 45);
  ctx.lineTo(W/2 - 70 + 10 * Math.sin(t), H/2 + 55);
  ctx.stroke();

  ctx.restore();
}
